{
  "conditions": {
    "basis_identification": {
      "status": "review",
      "note": "The record identifies specific incidents, dates, and RMOs involved, but the Agency's investigative basis for concluding no discrimination is entirely absent—only the conclusion is stated, not the evidence or reasoning supporting it."
    },
    "reasoning_traceability": {
      "status": "gap",
      "note": "The final decision provides no traceability from evidence (ROI findings, witness statements, comparator analysis) to the conclusion that Complainant 'failed to prove' discrimination; the decision text is outcome-only without analytical pathway."
    },
    "cold_reviewer_clarity": {
      "status": "gap",
      "note": "A reviewer reading only this record cannot reconstruct why the Agency rejected the discrimination claim—no summary of investigative findings, factual determinations, or legal application is provided."
    },
    "accountability_support": {
      "status": "gap",
      "note": "The record states the conclusion but omits the evidentiary record (ROI contents, comparator data, credibility assessments, temporal analysis of causation) necessary to support the 'failed to prove' determination."
    },
    "temporal_reconstructability": {
      "status": "pass",
      "note": "Event sequence is clearly established: termination on September 18, 2020; complaint filed October 9, 2020; investigation conducted; ROI issued; final decision March 3, 2022, with regulatory timeline reference."
    }
  },
  "remediation_note": "The record must incorporate a summary of the ROI's factual findings, the Agency's comparator analysis (if applicable), and explicit reasoning explaining why the evidence fails to establish discrimination on race, color, or age bases. The final decision should articulate the legal standard applied and how specific evidence does or does not satisfy the burden of proof.",
  "finding": {
    "ai_function": "summarization",
    "condition_triggered": "basis_identification, reasoning_traceability, cold_reviewer_clarity, accountability_support",
    "compliant_version": "Append to the final decision a section titled 'Agency Findings and Analysis' summarizing: (1) factual findings from the ROI with supporting evidence; (2) identification of any similarly situated comparators and why they distinguish Complainant's treatment; (3) explanation of temporal sequence and causation analysis; (4) application of the McDonnell Douglas burden-shifting framework or applicable legal standard; and (5) explicit statement of why the evidence is insufficient to prove intentional discrimination."
  }
}
